-- Server-owned additions for features introduced by the updated UI.
ALTER TABLE profiles ADD COLUMN token_valid_after INTEGER NOT NULL DEFAULT 0;
ALTER TABLE families ADD COLUMN preferred_channel TEXT NOT NULL DEFAULT 'internet' CHECK(preferred_channel IN ('internet','phone'));
ALTER TABLE families ADD COLUMN questionnaire_reviews TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(questionnaire_reviews));
ALTER TABLE documents ADD COLUMN optional INTEGER NOT NULL DEFAULT 0 CHECK(optional IN (0,1));
ALTER TABLE documents ADD COLUMN purpose TEXT NOT NULL DEFAULT '';
ALTER TABLE documents ADD COLUMN subject TEXT NOT NULL DEFAULT '';
ALTER TABLE documents ADD COLUMN period TEXT NOT NULL DEFAULT '';
ALTER TABLE documents ADD COLUMN source_hint TEXT NOT NULL DEFAULT '';
ALTER TABLE documents ADD COLUMN consent TEXT CHECK(consent IS NULL OR json_valid(consent));
ALTER TABLE family_tasks ADD COLUMN document_id TEXT REFERENCES documents(id);
ALTER TABLE family_tasks ADD COLUMN request_kind TEXT CHECK(request_kind IN ('help','correction'));
ALTER TABLE family_tasks ADD COLUMN source_id TEXT;
ALTER TABLE family_tasks ADD COLUMN source_kind TEXT CHECK(source_kind IN ('familyTask','followUp'));
ALTER TABLE meeting_followups ADD COLUMN document_id TEXT REFERENCES documents(id);
ALTER TABLE notifications ADD COLUMN target_kind TEXT;
ALTER TABLE notifications ADD COLUMN target_id TEXT;
CREATE TABLE partners(id TEXT PRIMARY KEY,profile_id TEXT NOT NULL UNIQUE REFERENCES profiles(id),name TEXT NOT NULL,code TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE referrals(id TEXT PRIMARY KEY,public_id TEXT NOT NULL UNIQUE,partner_id TEXT NOT NULL REFERENCES partners(id),family_id TEXT NOT NULL UNIQUE REFERENCES families(id),registered_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('registered','in_treatment','completed','cancelled')));
CREATE INDEX referrals_partner ON referrals(partner_id);
CREATE TABLE commission_entries(id TEXT PRIMARY KEY,partner_id TEXT NOT NULL REFERENCES partners(id),kind TEXT NOT NULL CHECK(kind IN('credit','payout')),referral_id TEXT REFERENCES referrals(public_id),amount_agorot INTEGER NOT NULL CHECK(amount_agorot>0 AND amount_agorot<=100000000),note TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES profiles(id));
CREATE INDEX commissions_partner ON commission_entries(partner_id);
CREATE TABLE final_reports(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL UNIQUE REFERENCES meetings(id),family_id TEXT NOT NULL REFERENCES families(id),revision INTEGER NOT NULL CHECK(revision>0),status TEXT NOT NULL CHECK(status IN('draft','approved')),content TEXT NOT NULL CHECK(json_valid(content)),snapshot TEXT CHECK(snapshot IS NULL OR json_valid(snapshot)),updated_at TEXT NOT NULL);
CREATE TABLE final_report_history(id TEXT PRIMARY KEY,report_id TEXT NOT NULL REFERENCES final_reports(id),revision INTEGER NOT NULL,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),UNIQUE(report_id,revision));
CREATE TABLE document_versions(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),object_key TEXT NOT NULL UNIQUE,file_name TEXT NOT NULL,mime_type TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>0 AND size<=20971520),sha256 TEXT NOT NULL,uploaded_by TEXT NOT NULL REFERENCES profiles(id),created_at TEXT NOT NULL);
CREATE TABLE database_revision(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT INTO database_revision VALUES(1,0);
CREATE TABLE transaction_assertions(id TEXT PRIMARY KEY,valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE rate_limits(key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TRIGGER immutable_audit_update BEFORE UPDATE ON audit_log BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_audit_delete BEFORE DELETE ON audit_log BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_report_update BEFORE UPDATE ON final_report_history BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_report_delete BEFORE DELETE ON final_report_history BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_commission_update BEFORE UPDATE ON commission_entries BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_commission_delete BEFORE DELETE ON commission_entries BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
